import {useMuscleGroup} from "@/context/MuscleGroupContext";

interface HumanFrontProps {
    width?: number;
    height?: number;
}
/**
 * HumanFront is a reusable component that displays the front view of a human body as an SVG.
 * It uses the MuscleGroup context to toggle the selected muscle groups and dynamically changes
 * the color of the SVG paths based on the current theme's colors.
 *
 * The component is designed to allow users to interact with individual muscle groups by tapping
 * on different areas of the front view. Each muscle group changes color when it is active,
 * providing a visual indication of the selected muscle groups.
 *
 * @param {HumanFrontProps} props - The properties for configuring the HumanFront component.
 * @param {number} [props.width=300] - Optional: The width of the SVG. Defaults to 300.
 * @param {number} [props.height=500] - Optional: The height of the SVG. Defaults to 500.
 *
 * @example
 * <HumanFront width={300} height={500} />
 *
 */
